    parameter int WIDTH=27,
    parameter int FRAME_T=8192,
    parameter int ADDRESS_BITS=8,
    parameter int ROW_W=(FRAME_T>1 ? $clog2(FRAME_T) : 1),
    parameter int MAP_W=(ADDRESS_BITS>0 ? ADDRESS_BITS*ROW_W : 1),
    parameter logic [MAP_W-1:0] ADDRESS_ROW_POSITIONS=104'h6002c014009004001c00c005,
